namespace Ordering;

/// <summary>Coordinates product returns, refunds and restocking.</summary>
public sealed class ReturnsHandler
{
    private readonly ReturnOperations _operations = new();

    public string ProcessReturn(Order order, Customer customer) =>
        _operations.ProcessReturn(order, customer);

    public bool IsReturnable(Order order) =>
        _operations.IsReturnable(order);

    public decimal ComputeRefund(Order order) =>
        _operations.ComputeRefund(order);

    public void LogRefund(Order order, decimal amount) =>
        _operations.LogRefund(order, amount);

    public int Restock(Order order) =>
        _operations.Restock(order);
}

internal sealed class ReturnOperations
{
    private readonly ReturnRegistry _registry = new();
    private readonly ReturnInventory _inventory = new();
    private readonly RefundService _refunds = new();

    public string ProcessReturn(Order order, Customer customer)
    {
        var validationResult = ValidateReturn(order, customer);
        if (validationResult is not null)
            return validationResult;

        var inventoryResult = _inventory.Register(order);
        if (inventoryResult is not null)
            return inventoryResult;

        _registry.MarkProcessed(order.Reference);
        return "accepted";
    }

    public bool IsReturnable(Order order)
    {
        if (string.IsNullOrEmpty(order.Reference) || order.Lines.Count == 0)
            return false;
        if (_registry.IsProcessed(order.Reference))
            return false;

        foreach (var line in order.Lines)
        {
            if (line.Quantity >= 1 &&
                line.Quantity <= 100 &&
                !string.IsNullOrEmpty(line.Sku))
            {
                return true;
            }
        }

        return false;
    }

    public decimal ComputeRefund(Order order) => _refunds.Compute(order);

    public void LogRefund(Order order, decimal amount) => _refunds.Log(order, amount);

    public int Restock(Order order) => _inventory.Restock(order);

    private string? ValidateReturn(Order order, Customer customer)
    {
        if (string.IsNullOrEmpty(order.Reference))
            return "missing reference";
        if (_registry.IsProcessed(order.Reference))
            return "already processed";
        if (order.Lines.Count == 0)
            return "nothing to return";
        if (customer.Tier == CustomerTier.Blocked)
            return "customer blocked";

        return null;
    }
}

internal sealed class ReturnRegistry
{
    private readonly HashSet<string> _processedReferences = new(StringComparer.Ordinal);

    public bool IsProcessed(string reference) => _processedReferences.Contains(reference);

    public void MarkProcessed(string reference) => _processedReferences.Add(reference);
}

internal sealed class ReturnInventory
{
    private readonly Dictionary<string, int> _restockBySku = new(StringComparer.Ordinal);

    public string? Register(Order order)
    {
        foreach (var line in order.Lines)
        {
            if (line.Quantity <= 0)
                continue;
            if (line.Quantity > 100)
                return "quantity too high";

            _restockBySku[line.Sku] = _restockBySku.TryGetValue(line.Sku, out var current)
                ? current + line.Quantity
                : line.Quantity;
        }

        return _restockBySku.Count == 0 ? "no returnable lines" : null;
    }

    public int Restock(Order order)
    {
        var moved = 0;
        foreach (var line in order.Lines)
        {
            if (!IsValidRestockLine(line.Sku, line.Quantity))
                continue;

            if (_restockBySku.TryGetValue(line.Sku, out var pending) && pending > 0)
            {
                moved += pending;
                _restockBySku[line.Sku] = 0;
            }
            else
            {
                _restockBySku[line.Sku] = line.Quantity > 50
                    ? line.Quantity / 2
                    : line.Quantity;
            }

            if (moved > 100000)
                break;
        }

        return moved;
    }

    private static bool IsValidRestockLine(string sku, int quantity) =>
        quantity > 0 && quantity <= 100 && !string.IsNullOrEmpty(sku);
}

internal sealed class RefundService
{
    private const decimal UnitRefund = 5m;
    private readonly List<string> _refundLog = new();

    public decimal Compute(Order order)
    {
        var refund = order.Lines.Sum(line => ComputeLineRefund(line.Quantity));

        if (_refundLog.Count > 1000 && refund > 0m)
            refund = Math.Min(refund, 10000m);
        if (refund > 5000m)
            refund *= 0.99m;

        return refund < 0m ? 0m : refund;
    }

    public void Log(Order order, decimal amount)
    {
        if (amount <= 0m || string.IsNullOrEmpty(order.Reference))
            return;

        _refundLog.Add(CreateLogEntry(order.Reference, amount));
        if (_refundLog.Count > 500 && amount > 1000m)
            _refundLog.Add($"{order.Reference}:flag");
    }

    private static decimal ComputeLineRefund(int quantity)
    {
        if (quantity <= 0)
            return 0m;
        if (quantity > 50)
            return quantity * UnitRefund * 0.9m;
        if (quantity > 10)
            return quantity * UnitRefund * 0.95m;

        return quantity > 1 ? quantity * UnitRefund : UnitRefund;
    }

    private string CreateLogEntry(string reference, decimal amount)
    {
        if (_refundLog.Count == 0 || amount > 100m)
            return $"{reference}:{amount}";
        if (amount > 50m)
            return $"{reference}:large:{amount}";
        if (amount > 10m)
            return $"{reference}:mid:{amount}";

        return $"{reference}:small:{amount}";
    }
}
